import { describe, expect, it, vi } from "vitest";
import {
  summarizeChecksImpl,
  updateCommitStatus,
  type CheckRunResult,
} from "../../src/summarize-checks/summarize-checks.ts";
import { createMockCore, createMockGithub } from "../mocks.ts";
import { statusContext, summaryResponse } from "./summary-data-fixtures.ts";

const statusName = "Automated merging requirements met";
const pendingDescription =
  "The requirements for merging this PR are still being evaluated. Please wait.";
const previousRun = "https://github.com/owner/repo/actions/runs/1";
const currentRun = "https://github.com/owner/repo/actions/runs/2";
const pendingBody =
  "<h2>Next Steps to Merge</h2>⌛ Please wait. Next steps to merge this PR are being evaluated by automation. ⌛";
const comment = (body: string, run = previousRun) =>
  `${body}<br /><br />Comment generated by <a href="${run}">summarize-checks</a> workflow run.\n<!-- NextStepsToMerge -->`;

async function summarize(github: ReturnType<typeof createMockGithub>) {
  const core = createMockCore();
  core.summary.addLink = vi.fn().mockReturnValue(core.summary);
  core.summary.addHeading = vi.fn().mockReturnValue(core.summary);
  core.summary.addCodeBlock = vi.fn().mockReturnValue(core.summary);
  await summarizeChecksImpl(
    github,
    core,
    "owner",
    "repo",
    123,
    "head-sha",
    "workflow_run",
    "main",
    currentRun,
  );
}

describe("summary writes", () => {
  it("does not rewrite unchanged content or statuses just to refresh run URLs", async () => {
    const github = createMockGithub();
    github.graphql.mockResolvedValue(
      summaryResponse({
        comments: [{ databaseId: 42, body: comment(pendingBody) }],
        contexts: [statusContext({ context: statusName, description: pendingDescription })],
      }),
    );

    await summarize(github);

    expect(github.rest.issues.updateComment).not.toHaveBeenCalled();
    expect(github.rest.issues.createComment).not.toHaveBeenCalled();
    expect(github.rest.repos.createCommitStatus).not.toHaveBeenCalled();
    expect(github.graphql).toHaveBeenCalledTimes(1);
    expect(github.rest.repos.listCommitStatusesForRef).not.toHaveBeenCalled();
    expect(github.rest.issues.listComments).not.toHaveBeenCalled();
  });

  it("updates changed guidance with the current run link", async () => {
    const github = createMockGithub();
    github.graphql.mockResolvedValue(
      summaryResponse({
        comments: [
          { databaseId: 42, body: comment("<h2>Next Steps to Merge</h2>Previous guidance") },
        ],
      }),
    );

    await summarize(github);

    expect(github.rest.issues.updateComment).toHaveBeenCalledExactlyOnceWith({
      owner: "owner",
      repo: "repo",
      comment_id: 42,
      body: comment(pendingBody, currentRun),
    });
    expect(github.rest.repos.createCommitStatus).toHaveBeenCalledWith(
      expect.objectContaining({ state: "pending", target_url: currentRun }),
    );
  });

  it("creates the first comment and status", async () => {
    const github = createMockGithub();
    github.graphql.mockResolvedValue(summaryResponse());
    github.rest.issues.createComment.mockResolvedValue({ data: { id: 42 } });

    await summarize(github);

    expect(github.rest.issues.createComment).toHaveBeenCalledExactlyOnceWith({
      owner: "owner",
      repo: "repo",
      issue_number: 123,
      body: comment(pendingBody, currentRun),
    });
    expect(github.rest.repos.createCommitStatus).toHaveBeenCalledTimes(1);
    expect(github.rest.issues.listComments).not.toHaveBeenCalled();
  });

  it("does not publish anything when GraphQL fails", async () => {
    const github = createMockGithub();
    github.graphql.mockRejectedValue(new Error("GraphQL rate limit exceeded"));
    await expect(summarize(github)).rejects.toThrow("GraphQL rate limit exceeded");
    expect(github.rest.issues.addLabels).not.toHaveBeenCalled();
    expect(github.rest.issues.removeLabel).not.toHaveBeenCalled();
    expect(github.rest.issues.updateComment).not.toHaveBeenCalled();
    expect(github.rest.issues.createComment).not.toHaveBeenCalled();
    expect(github.rest.repos.createCommitStatus).not.toHaveBeenCalled();
  });
});

describe("updateCommitStatus", () => {
  const result: CheckRunResult = {
    name: statusName,
    result: "pending",
    summary: pendingDescription,
    target_url: currentRun,
  };

  it.each([
    { context: statusName, state: "failure", description: pendingDescription },
    { context: statusName, state: "pending", description: "Different description" },
    { context: "Other check", state: "pending", description: pendingDescription },
    undefined,
  ])("publishes when the prior status is different or missing (%j)", async (existing) => {
    const github = createMockGithub();
    await updateCommitStatus(github, createMockCore(), "owner", "repo", "sha", result, existing);
    expect(github.rest.repos.createCommitStatus).toHaveBeenCalledTimes(1);
  });

  it("compares the description after applying GitHub's length limit", async () => {
    const github = createMockGithub();
    const summary = "x".repeat(200);
    await updateCommitStatus(
      github,
      createMockCore(),
      "owner",
      "repo",
      "sha",
      { ...result, summary },
      { context: statusName, state: "pending", description: `${"x".repeat(137)}...` },
    );
    expect(github.rest.repos.createCommitStatus).not.toHaveBeenCalled();
  });

  it("does not hide write failures", async () => {
    const github = createMockGithub();
    github.rest.repos.createCommitStatus.mockRejectedValue(new Error("rate limited"));
    await expect(
      updateCommitStatus(github, createMockCore(), "owner", "repo", "sha", result),
    ).rejects.toThrow("rate limited");
  });
});
